def transform_numbers(a, b):
    if len(a) != len(b):
        return -1

    moves = []
    i = len(a) - 1

    while i >= 0:
        if a[i] != b[i]:
            moves.append((i, 1) if a[i] > b[i] else (i, -1))
            i -= 1
        else:
            i -= 1

    if i != -1:
        for j in range(len(moves) - 1, -1, -1):
            moves[j] = (j + 1, moves[j][1] * -1)

    return len(moves) + max(1, len(moves))

