from itertools import accumulate

def minimize_score(sequence: List[int], k: int, p: int) -> int:
    cumulative_sums = list(accumulate(sequence))
    func = lambda s_p: sum([d % p for d in s_p])
    return min([func([x if k == 1 else sequence[cumulative_sums.index(offset) : (k - 1) * offset + len(sequence) - x[cumulative_sums.index(offset)]] for x in partitions(cumulative_sums, k)]) for offset in range(len(sequence) * (k - 1) + 1)])

def partitions(arr: List[int], k: int) -> List[List[int]]:
    return [arr[i*k:(i+1)*k] for i in range(k)]
