import sys

def min_coins_to_win():
    n = int(input().strip())
    a = int(input().strip(), 10**n)
    b = int(input().strip(), 10**n)

    if abs(str(a) - str(b)) != n:
        return -1

    moves = []

    while a != b:
        moves.append((0, 0))

        for i in range(n):
            if a < b:
                break
            if abs(a - b) == 1:
                moves.append((i, 1))
                a += 1
                break

            if a[i] == '0':
                continue

            a = str(a)
            j = i + 1

            if a[i] == '9':
                a = '9' + '0'*(len(a) - 1) + str(0)
            elif a[j] == '0':
                a = str(0) + '1'*(len(a) - 2) + str(0)
            else:
                a = a[:i+1] + str(int(a[i+1]) - 1) + a[i+2:]

            moves.append((i, -1))

    ans = [x for _, x in moves[::2]]
    flips = [x for _, x in moves[1::2]]

    if abs(len(ans) - len(flips)) <= 1:
        return str(len(ans)) + "\n" + "".join(map(str, (*ans, *reversed(flips)))))
    else:
        return str(len(ans) + 1) + "\n" + "".join(map(str, (*ans, *reversed(flips)))))

