    return abs(a[0] - b[0]) + abs(a[1] - b[1]) + abs(a[2] - b[2])

def find_optimal_point(roses):
    min_max_manhattan = float('inf')
    optimal_point = None

    for x in range(1019):
        for y in range(1019):
            for z in range(1019):
                total_distance = 0
                for rose in roses:
                    distance = manhattan_distance(rose, (x, y, z))
                    total_distance += distance
                if total_distance < min_max_manhattan:
                    min_max_manhattan = total_distance
                    optimal_point = (x, y, z)

