from collections import defaultdict
from heapq import heappop, heappush

def dijkstra(graph, start):
    distances = defaultdict(lambda: float('inf'))
    distances[start] = 0
    queue = [(0, start)]

    while queue:
        current_distance, current_vertex = heappop(queue)

        if current_distance > distances[current_vertex]:
            continue

        for neighbor, weight in graph[current_vertex].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(queue, (distance, neighbor))

    return distances

def solve_queries(n, edges, queries):
    graph = defaultdict(dict)

    for a, b in edges:
        u, v = sorted([a, b])
        graph[u][v] = graph[v][u] = 1

    for query in queries:
        if query.startswith("C"):
            i, w = map(int, query.split())
            graph[i][i] = w
        elif query.startswith("A"):
            a, b = map(int, query.split())
            path_distances = dijkstra(graph, a)

            if path_distances[b] < float('inf'):
                print(path_distances[b])
            else:
                print(1)

