from collections import defaultdict

def parse_matrix(matrix):
    n = len(matrix)
    adjacency_list = defaultdict(list)
    in_degree = [0] * n

    for i in range(n):
        for j in range(i):
            if matrix[i][j] == 'A':
                adjacency_list[i].append(j)
                adjacency_list[j].append(i)
                in_degree[i] += 1
                in_degree[j] += 1
            elif matrix[i][j] == 'X':
                adjacency_list[i].append(j)
                adjacency_list[j].append(i)
                in_degree[i] += 1
                in_degree[j] += 1
            elif matrix[i][j] == 'O':
                adjacency_list[i].append(j)
                adjacency_list[j].append(i)
                in_degree[i] += 1
                in_degree[j] += 1
            elif matrix[i][j] == '-':
                continue

    return adjacency_list, in_degree

def construct_graph(adjacency_list, in_degree):
    nodes = list(range(len(adjacency_list)))
    graph = [[] for _ in range(len(adjacency_list))]
    indegree = defaultdict(int)
    for node in nodes:
        indegree[node] = in_degree[node]

    for u in range(len(adjacency_list)):
        for v in adjacency_list[u]:
            graph[u].append(v)
            indegree[v] += 1

    min_edges = indegree[0]
    for u in range(len(adjacency_list)):
        min_edges = min(min_edges, indegree[u])

    return min_edges

def is_consistent(adjacency_list, in_degree, k):
    if in_degree[0] != k:
        return False

    for node in nodes:
        if len(adjacency_list[node]) != in_degree[node]:
            return False

    return True

def find_min_edges(matrix):
    n = len(matrix)
    adjacency_list, in_degree = parse_matrix(matrix)

    if not is_consistent(adjacency_list, in_degree, n):
        return -1

    return construct_graph(adjacency_list, in_degree)

