from math import inf

def coverage_distance(cinema, house, shop):
    dists = [cinema[0] - shop[0], cinema[1] - shop[1], shop[0] - house[0], shop[1] - house[1]]
    dists.sort()
    return max(dists)

def shortest_distance(cinema, house, shop):
    manhattan_distances = [abs(cinema[0] - shop[0]) + abs(cinema[1] - shop[1]),
                           abs(house[0] - shop[0]) + abs(house[1] - shop[1]),
                           abs(cinema[0] - house[0]) + abs(cinema[1] - house[1]),
                           abs(house[0] - cinema[0]) + abs(house[1] - cinema[1])]

    min_distance = min(manhattan_distances)
    if sum(dists) - min_distance <= 0:
        return 0
    max_distance = min_distance
    for dist in manhattan_distances[1:]:
        if dist < max_distance:
            max_distance = dist
    return max_distance

