            roses[i][0] + (roses[(i + 1) % n][1] - roses[i][1]) // 2)) 
                          for roses in zip(roses, roses[i + 1:n]))
        right_sum = sum(abs(rose[1] - (
            (roses[(i + 1) % n][0] - roses[i][0]) // 2 + roses[i][1])) 
                          for roses in zip(roses, roses[i + 1:n]))
        if left_sum < right_sum:
