import heapq

def heuristic(q, garden):
    manhattan = lambda x, y: sum(abs(x[i] - y[i]) for i in range(3))
    return min(manhattan(p, q) for p in garden)

def dijkstra(start, garden):
    distances = {pos: float('inf') for pos in garden}
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_pos = heapq.heappop(priority_queue)
        if current_distance > distances[current_pos]:
            continue

        for neighbor_pos, neighbor_distance in garden:
            distance = manhattan(current_pos, neighbor_pos)
            if distance < manhattan(neighbor_pos, start) + distances[neighbor_pos]:
                distances[neighbor_pos] = distance
                heapq.heappush(priority_queue, (manhattan(neighbor_pos, start) + distances[neighbor_pos], neighbor_pos))

    return distances

def manhattan(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1]) + abs(a[2] - b[2])

