    optimal_position = None

    while True:
        distances = dijkstra(start, garden)
        best_possible_distances = {start: 0}

        for i in range(n):
            start_manhattan = manhattan(start, garden[i])
            best_possible_distances[garden[i]] = distances[garden[i]] + start_manhattan

        possible_distances = [(best_possible_distances[pos], pos) for pos in best_possible_distances if best_possible_distances[pos] < best_distance]

