import sys

def evaluate_expression(expression):
    evaluated = []
    current = ''
    for char in expression:
        if char == '(':
            evaluated.append(('l', current))
            current = ''
        elif char == ')':
            a, result = evaluated.pop()
            if current == '' and a != 'var':
                evaluated.pop()  # Discard the nested expression if it's not a variable
                evaluated.append(('r', (a if char == '|' else '&') if result == ('l', 'var') else result))
            else:
                evaluated.append(('r', result))
        else:
            current += char
    return evaluated[0][1]

def evaluate(n, expression):
    seen = set()
    for i in range(n ** 2):
        for j in range(n ** 2):
            evaluated = evaluate_expression(expression.replace('?', str((i, j))))
            if evaluated in seen:
                return 'YES'
            seen.add(evaluated)
    return 'NO'

