def evaluate_formula(formula):
    stack = []
    for ch in formula:
        if ch == '(':
            stack.append(ch)
        elif ch == ')':
            while stack and stack[-1] != '(':
                operator, a, b = stack.pop(), stack.pop(), stack.pop()
                if operator == '|':
                    result = '0' if operator(a, b) else '1'
                elif operator == '&':
                    result = '1' if operator(a, b) else '0'
                elif operator == '^':
                    result = '1' if operator(a, b) else '0'
                stack.append(result)
        elif ch in '01?|&^':
            stack.append(ch)
    return stack[0]

