import sys
from collections import defaultdict

def max_depth(graph):
    max_depth = 0
    for i in range(len(graph) - 1):
        visited = set()
        count = 0
        vertex = i + 1
        while vertex in visited:
            visited.add(vertex)
            count += 1
            for neighbor in graph[vertex]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    vertex = neighbor
            vertex = graph[vertex].pop() if graph[vertex] else None
        max_depth = max(max_depth, count)
    return max_depth

def minimum_seconds(N):
    for i in range(N):
        if N % (i + 2) == 0:
            return N // (i + 2) * (i + 1)
    return N

def main():
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    graph = defaultdict(set)
    c = data[1::]
    for i in range(N - 1):
        if c[i * 2] == c[i * 2 + 1]:
            x, y = map(int, data[i * 2 + 2: i * 2 + 4])
            x, y = x - 1, y - 1
            graph[x].add(y)
            graph[y].add(x)
        else:
            graph[i + 1].add(i + 2)
            graph[i + 2].add(i + 1)
    return minimum_seconds(len(c))

if __name__ == "__main__":
